function sumQuantities(events) {
  return events.reduce((sum, e) => sum + e.quantity, 0);
}

function apiCallCount(events) {
  return events
    .filter((e) => e.type === "api_call")
    .reduce((sum, e) => sum + e.quantity, 0);
}

function centsFor(event) {
  const rates = { api_call: 2, storage: 5 };
  return event.quantity * rates[event.type];
}

function totalCents(events) {
  const rates = { api_call: 2, storage: 5 };
  return events.reduce((sum, e) => sum + e.quantity * rates[e.type], 0);
}

function rateFor(type, tier) {
  const table =
    tier === "enterprise" ? { api_call: 1, storage: 4 } : { api_call: 2, storage: 5 };
  return table[type];
}

function apiCents(events, tier) {
  const rate = tier === "enterprise" ? 1 : 2;
  return events
    .filter((e) => e.type === "api_call")
    .reduce((sum, e) => sum + e.quantity * rate, 0);
}

function quantityByType(events) {
  const totals = { api_call: 0, storage: 0 };
  for (const e of events) totals[e.type] += e.quantity;
  return totals;
}

function applyMinimum(total, minimum) {
  return total < minimum ? minimum : total;
}

function calculateTotal(usageEvents, tier) {
  const cents =
    tier === "enterprise" ? { api_call: 1, storage: 4 } : { api_call: 2, storage: 5 };
  return usageEvents.reduce((sum, e) => sum + e.quantity * cents[e.type], 0);
}

function calculateTotal(usageEvents, tier) {
  const tables = {
    standard: { api_call: 2, storage: 5 },
    starter: { api_call: 3, storage: 6 },
    enterprise: { api_call: 1, storage: 4 },
  };
  const cents = tables[tier];
  if (!cents) throw new Error("Unknown tier: " + tier);
  return usageEvents.reduce((sum, e) => sum + e.quantity * cents[e.type], 0);
}

function calculateTotal(usageEvents, tier) {
  if (usageEvents.length === 0) return 0;
  const cents =
    tier === "enterprise" ? { api_call: 1, storage: 4 } : { api_call: 2, storage: 5 };
  const total = usageEvents.reduce((sum, e) => sum + e.quantity * cents[e.type], 0);
  return Math.max(total, 30);
}
